"""Portable generated bytes and fixed-plan validation at public entry points."""
import json
from pathlib import Path
import tempfile
import unittest
from pisa.io import write_csv,write_json
from pisa.immune import prepare,analyze


class OutputContracts(unittest.TestCase):
    def test_csv_and_json_are_lf_before_git_normalization(self):
        with tempfile.TemporaryDirectory() as directory:
            root=Path(directory)
            write_csv(root/'table.csv',[{'id':'1.1','value':3}])
            write_json(root/'record.json',{'id':'1.1','value':3})
            self.assertEqual((root/'table.csv').read_bytes(),b'id,value\n1.1,3\n')
            self.assertNotIn(b'\r\n',(root/'record.json').read_bytes())

    def test_generated_diagnostics_redact_profile_paths_without_changing_values(self):
        with tempfile.TemporaryDirectory() as directory:
            path=Path(directory)/'record.json'
            write_json(path,{'executable':r'C:\Users\Researcher\Python\python.exe',
                'nested':[{'error':'at /home/researcher/project/run.py'}],
                'n':10,'source_id':'19.2','sha256':'a'*64})
            record=json.loads(path.read_text())
            self.assertEqual(record['executable'],r'<USER_PROFILE>\Python\python.exe')
            self.assertEqual(record['nested'],[{'error':'at <USER_PROFILE>/project/run.py'}])
            self.assertEqual((record['n'],record['source_id'],record['sha256']),(10,'19.2','a'*64))

    def test_direct_science_entry_points_reject_unsupported_plan_before_io(self):
        cases=[{'endpoints':['unplanned']},{'confidence_level':0.90},
               {'multiple_testing':'none'},{'interpretation':'confirmatory'}]
        with tempfile.TemporaryDirectory() as directory:
            root=Path(directory)
            for function in (prepare,analyze):
                for settings in cases:
                    with self.subTest(function=function.__name__,settings=settings):
                        with self.assertRaisesRegex(ValueError,'Unsupported fixed immune'):
                            function(root,{'immune':settings})
            self.assertEqual(list(root.iterdir()),[])
